  ('retention', '{"softDeletedDays":30,"erasedTombstoneDays":30,"lapsedAccount":{"deleteAfterMonths":12,"noticeDaysBefore":[30,7,2]},"unconfirmedSignupDays":7,"billingRecordsYearsAfterFinancialYear":8,"registrantContactsDaysAfterLastDomain":90,"domainQuotesDays":30,"siteDailyViewsMonths":25,"consentsYearsAfterData":1,"dataRequests":{"keepYearsAfterClose":3,"responseDays":30,"reminderDays":[7,21],"escalateAfterDays":30},"auditLogMonths":13,"orphanMediaDays":30,"endedPolicySuggestDeleteYears":3}'::jsonb)
